import csv
for path in ['inputs/BatchCorrectedReadCounts_Zenodo.csv','inputs/Sample_annotated_Zenodo.csv','inputs/GeneMetaInfo_Zenodo.csv']:
    with open(path, newline='') as f:
        r=csv.reader(f); header=next(r)
        first=[]; seen=set(); dups=[]; n=0
        if path.endswith('Sample_annotated_Zenodo.csv'):
            idx=header.index('sample')
        else:
            idx=0
        for row in r:
            n+=1; val=row[idx]
            if val in seen and len(dups)<10: dups.append(val)
            seen.add(val)
        print(path, 'rows', n, 'unique', len(seen), 'dups_example', dups)
PY"

